function buildSection(section) {
    var metrics = section.metrics || [];
    var html = "";
    var i;
    var isOverview = section.code === "overview";
    var sectionIcon = section.icon || DECO_ICONS[section.code] || "bi-bar-chart";
    var chartsHtml = buildChartsRow(section);

    if (!isOverview && !chartsHtml) {
        return "";
    }

    if (isOverview) {
        html += "<div class=\"row sch-dash-row sch-dash-main-section\">";
        html += "<div class=\"col-12\">";
        html += "<div class=\"sch-dash-main-section-header\">";
        html += "<h5><i class=\"bi " + sectionIcon + " me-2\"></i>" + (section.title || "") + "</h5>";
        html += "</div></div></div>";

        html += "<div class=\"row sch-dash-row\">";
        for (i = 0; i < metrics.length; i++) {
            html += buildMetricCard(metrics[i]);
        }
        html += "</div>";
    }

    html += chartsHtml;
    return html;
}

private Dictionary<string, object> BuildEmptyChart(string chartId, string title, string chartType)
{
    Dictionary<string, object> dicChart = new Dictionary<string, object>();
    dicChart["id"] = chartId;
    dicChart["title"] = title;
    dicChart["type"] = chartType == null || chartType == "" ? "bar" : chartType;
    dicChart["items"] = new List<Dictionary<string, object>>();
    dicChart["empty"] = true;
    return dicChart;
}

