private Dictionary<string, object> BuildChartFromTable(
    string chartId,
    string title,
    string chartType,
    DataTable dtb,
    string labelColumn,
    string valueColumn,
    int intTopN,
    bool bolSortDesc)
{
    List<Dictionary<string, object>> lstItems = ExtractChartItems(dtb, labelColumn, valueColumn);
    lstItems = SortAndLimitChartItems(lstItems, intTopN, bolSortDesc);

    Dictionary<string, object> dicChart = new Dictionary<string, object>();
    dicChart["id"] = chartId;
    dicChart["title"] = title;
    dicChart["type"] = chartType;
    dicChart["items"] = lstItems;
    dicChart["empty"] = lstItems.Count == 0;
    return dicChart;
}

private List<Dictionary<string, object>> ExtractChartItems(
    DataTable dtb,
    string labelColumn,
    string valueColumn)
{
    List<Dictionary<string, object>> lstItems = new List<Dictionary<string, object>>();

    if (dtb == null)
        return lstItems;

    int intRow;
    for (intRow = 0; intRow < dtb.Rows.Count; intRow++)
    {
        DataRow drw = dtb.Rows[intRow];
        string strLabel = GetRowString(drw, labelColumn);
        decimal decValue = GetRowDecimal(drw, valueColumn);

        if (strLabel == "" && decValue == 0)
            continue;

        Dictionary<string, object> dicItem = new Dictionary<string, object>();
        dicItem["label"] = strLabel;
        dicItem["value"] = decValue;
        lstItems.Add(dicItem);
    }

    return lstItems;
}

private List<Dictionary<string, object>> SortAndLimitChartItems(
    List<Dictionary<string, object>> lstItems,
    int intTopN,
    bool bolSortDesc)
{
    if (lstItems == null)
        return new List<Dictionary<string, object>>();

    if (bolSortDesc && lstItems.Count > 1)
    {
        lstItems.Sort(CompareChartItemDesc);
    }

    if (intTopN > 0 && lstItems.Count > intTopN)
    {
        return lstItems.GetRange(0, intTopN);
    }

    return lstItems;
}

private int CompareChartItemDesc(
    Dictionary<string, object> dicLeft,
    Dictionary<string, object> dicRight)
{
    decimal decLeft = Convert.ToDecimal(dicLeft["value"]);
    decimal decRight = Convert.ToDecimal(dicRight["value"]);
    return decRight.CompareTo(decLeft);
}

